const sharp=require("sharp"),path=require("path"),input="public/images/hero-main.jpg",outputDir="public/images";async function optimizeHero(){console.log("🚀 Optimizing hero image...");try{await sharp(input).webp({quality:80}).toFile(path.join(outputDir,"hero-desktop.webp")),console.log("✅ Created hero-desktop.webp"),await sharp(input).resize(1200).webp({quality:80}).toFile(path.join(outputDir,"hero-tablet.webp")),console.log("✅ Created hero-tablet.webp"),await sharp(input).resize(600).webp({quality:80}).toFile(path.join(outputDir,"hero-mobile.webp")),console.log("✅ Created hero-mobile.webp"),console.log("✨ Hero optimization complete!")}catch(e){console.error("❌ Error during optimization:",e),process.exit(1)}}optimizeHero();